import itertools
import random

def has_cycle_of_length_at_most(edges, n, max_len):
    """Check if graph has any cycle of length <= max_len"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS/DFS to find cycles
    for start in range(n):
        # Use DFS to find cycles
        stack = [(start, -1, [start])]
        visited_states = set()
        while stack:
            node, parent, path = stack.pop()
            state = (node, parent, tuple(sorted(path)))
            if state in visited_states:
                continue
            visited_states.add(state)

            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor in path:
                    # Found a cycle
                    idx = path.index(neighbor)
                    cycle_len = len(path) - idx
                    if cycle_len <= max_len:
                        return True, cycle_len, path[idx:] + [neighbor]
                else:
                    if len(path) < max_len:
                        stack.append((neighbor, node, path + [neighbor]))
    return False, None, None

