def find_cycles_of_length(edges, n, target_len):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    cycles = []

    for start in range(n):
        stack = [(start, -1, [start])]
        while stack:
            node, parent, path = stack.pop()
            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor == start and len(path) == target_len:
                    cycles.append(path + [start])
                elif neighbor not in path and len(path) < target_len:
                    stack.append((neighbor, node, path + [neighbor]))

    # Deduplicate
    unique = []
    seen = set()
    for c in cycles:
        # Normalize by rotating to start with min vertex
        min_idx = c.index(min(c))
        normalized = tuple(c[min_idx:] + c[1:min_idx+1])
        if normalized not in seen:
            seen.add(normalized)
            unique.append(c)
    return unique

